async function fetch_verified_diagram_or_image(params, userSettings, resources) {
  const { search_query, visual_description, required_elements, exclusion_criteria, preferred_format } = params;
  const apiKey = userSettings?.geminiApiKey?.trim();

  if (!apiKey) {
    throw new Error("Gemini API Key is required. Please add your Google Gemini API Key in the plugin settings.");
  }

  if (!search_query || !visual_description) {
    throw new Error("Both 'search_query' and 'visual_description' are required parameters.");
  }

  // Helper to convert ArrayBuffer to Base64
  function arrayBufferToBase64(buffer) {
    let binary = "";
    const bytes = new Uint8Array(buffer);
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
      binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
  }

  // 1. Fetch Candidate Images from Wikimedia Commons API (CORS enabled)
  const wikimediaEndpoint = `https://commons.wikimedia.org/w/api.php?action=query&generator=search&gsrnamespace=6&gsrsearch=${encodeURIComponent(search_query)}&gsrlimit=6&prop=imageinfo&iiprop=url|mime|size|extmetadata&iiurlwidth=800&format=json&origin=*`;

  let candidates = [];
  try {
    const wikiRes = await fetch(wikimediaEndpoint);
    if (!wikiRes.ok) {
      throw new Error(`Wikimedia API returned status ${wikiRes.status}`);
    }
    const wikiData = await wikiRes.json();
    const pages = wikiData?.query?.pages || {};

    for (const pageId of Object.keys(pages)) {
      const page = pages[pageId];
      const info = page?.imageinfo?.[0];
      if (!info) continue;

      const mime = (info.mime || "").toLowerCase();
      // Filter for standard image formats supported by Gemini Vision
      if (mime.includes("image/jpeg") || mime.includes("image/png") || mime.includes("image/webp") || mime.includes("image/gif") || mime.includes("image/svg+xml")) {
        const directUrl = info.thumburl || info.url;
        const origUrl = info.url;
        const desc = info.extmetadata?.ObjectName?.value || info.extmetadata?.ImageDescription?.value || page.title;
        candidates.push({
          title: page.title.replace(/^File:/i, ""),
          mimeType: mime === "image/svg+xml" ? "image/png" : mime, // thumbnail of SVG is PNG
          renderUrl: directUrl,
          originalUrl: origUrl,
          filePageUrl: info.descriptionurl || `https://commons.wikimedia.org/wiki/${encodeURIComponent(page.title)}`,
          metaDescription: typeof desc === "string" ? desc.replace(/<[^>]*>?/gm, "").slice(0, 300) : ""
        });
      }
    }
  } catch (err) {
    return JSON.stringify({
      status: "search_failed",
      error: `Failed to search image repository: ${err.message}`
    });
  }

  if (candidates.length === 0) {
    return JSON.stringify({
      status: "no_results",
      message: `No candidate images found on Wikimedia Commons matching search query: "${search_query}".`
    });
  }

  // 2. Multimodal Vision Gating with Gemini 3.5 Flash Lite
  const evaluationLog = [];
  let verifiedImage = null;

  for (let i = 0; i < Math.min(candidates.length, 4); i++) {
    const candidate = candidates[i];
    try {
      // Fetch image bytes to base64 for Gemini multimodal input
      const imgRes = await fetch(candidate.renderUrl);
      if (!imgRes.ok) continue;
      const imgBuffer = await imgRes.arrayBuffer();
      const base64Data = arrayBufferToBase64(imgBuffer);
      const mimeType = candidate.mimeType.includes("png") ? "image/png" : (candidate.mimeType.includes("webp") ? "image/webp" : "image/jpeg");

      const geminiEndpoint = `https://generativelanguage.googleapis.com/v1beta/models/gemini-3.5-flash-lite:generateContent?key=${apiKey}`;

      const promptText = `You are a strict, objective visual inspection gatekeeper.
Analyze this image against the user's required criteria:
- Expected Subject: ${visual_description}
- Required Visual Elements: ${required_elements || 'Accurate visual representation of the concept'}
- Exclusion Criteria: ${exclusion_criteria || 'None'}
- Preferred Format: ${preferred_format || 'any'}
- Candidate Title & Context: ${candidate.title} (${candidate.metaDescription})

Determine if this image is genuine, clear, and accurately portrays what was requested.
Return ONLY valid JSON matching this schema:
{
  "is_valid": true or false,
  "confidence_score": 0.0 to 1.0,
  "reason": "Clear explanation of what was visually detected and why it passes or fails",
  "accurate_caption": "Concise factual caption describing what is visually shown"
}`;

      const payload = {
        contents: [
          {
            parts: [
              {
                inlineData: {
                  mimeType: mimeType,
                  data: base64Data
                }
              },
              {
                text: promptText
              }
            ]
          }
        ],
        generationConfig: {
          responseMimeType: "application/json",
          temperature: 0.1
        }
      };

      const evalRes = await fetch(geminiEndpoint, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(payload)
      });

      if (!evalRes.ok) {
        const errText = await evalRes.text();
        evaluationLog.push({ candidate: candidate.title, error: `Gemini API error: ${evalRes.status}` });
        continue;
      }

      const evalData = await evalRes.json();
      const rawText = evalData?.candidates?.[0]?.content?.parts?.[0]?.text;
      if (!rawText) continue;

      const verdict = JSON.parse(rawText);
      evaluationLog.push({
        candidate: candidate.title,
        is_valid: verdict.is_valid,
        confidence: verdict.confidence_score,
        reason: verdict.reason
      });

      if (verdict.is_valid && (verdict.confidence_score === undefined || verdict.confidence_score >= 0.7)) {
        verifiedImage = {
          imageUrl: candidate.renderUrl,
          originalUrl: candidate.originalUrl,
          sourcePage: candidate.filePageUrl,
          title: candidate.title,
          caption: verdict.accurate_caption || candidate.title,
          verificationReason: verdict.reason,
          confidence: verdict.confidence_score
        };
        break; // Found our verified high-quality match
      }
    } catch (e) {
      evaluationLog.push({ candidate: candidate.title, error: e.message });
    }
  }

  // 3. Return structured verification payload
  if (verifiedImage) {
    return JSON.stringify({
      status: "verified_match_found",
      markdown_embed: `![${verifiedImage.caption}](${verifiedImage.imageUrl})\n*Verified Visual Grounding: ${verifiedImage.caption} ([Source: Wikimedia Commons](${verifiedImage.sourcePage}))*`,
      verified_details: verifiedImage,
      instructions_for_ai: "Insert the provided markdown_embed directly into your response where relevant, referencing the specific visual structures depicted."
    }, null, 2);
  } else {
    return JSON.stringify({
      status: "verification_rejected",
      message: "Searched candidates failed strict visual verification. None of the images accurately matched the required visual description without flaws, ambiguities, or missing features.",
      audit_log: evaluationLog,
      instructions_for_ai: "Do NOT hallucinate or insert an unverified image. Inform the user that candidate visuals were retrieved but rejected by the vision gatekeeper for lack of accuracy."
    }, null, 2);
  }
}
